import{_ as a,o,c as t,a3 as r}from"./chunks/framework.BkJHvlZ8.js";const u=JSON.parse('{"title":"运维与排查","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operations.md","filePath":"guide/operations.md","lastUpdated":1787901540000}'),d={name:"guide/operations.md"};function i(l,e,c,n,s,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="运维与排查" tabindex="-1">运维与排查 <a class="header-anchor" href="#运维与排查" aria-label="Permalink to &quot;运维与排查&quot;">​</a></h1><h2 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h2><p>ApeAdmin 为 API 请求生成请求 ID，并在 <code>sys_log</code> 中记录方法、路径、状态码、耗时、用户和客户端信息。MCP 调用另有 <code>McpAuditLog</code>，可在管理台查看工具调用结果和失败原因。</p><p>排查插件问题时优先查看启动日志、插件 <code>runtime_state</code> / <code>last_error</code>、请求 ID 对应的 <code>sys_log</code>，以及浏览器 Network 中的 API 响应。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="菜单出现-404" tabindex="-1">菜单出现 404 <a class="header-anchor" href="#菜单出现-404" aria-label="Permalink to &quot;菜单出现 404&quot;">​</a></h3><p>检查菜单 <code>component</code> 是否能在 <code>frontend/src/views</code> 下找到同名 <code>.vue</code> 文件，大小写必须一致；然后退出管理台并重新加载用户菜单。</p><h3 id="插件显示启用但接口不存在" tabindex="-1">插件显示启用但接口不存在 <a class="header-anchor" href="#插件显示启用但接口不存在" aria-label="Permalink to &quot;插件显示启用但接口不存在&quot;">​</a></h3><p>检查插件的 <code>register(app)</code> 是否执行成功，以及是否存在重复前缀。必要时先停用插件，再重新启用；不要直接删除正在运行的插件目录。</p><h3 id="ai-文档分析失败" tabindex="-1">AI 文档分析失败 <a class="header-anchor" href="#ai-文档分析失败" aria-label="Permalink to &quot;AI 文档分析失败&quot;">​</a></h3><p>确认后台已配置 DeepSeek API Key、模型和网络访问；检查上传包是否超过大小/文件数限制，是否包含路径穿越、符号链接或加密文件。</p><h3 id="官网页面资源-404" tabindex="-1">官网页面资源 404 <a class="header-anchor" href="#官网页面资源-404" aria-label="Permalink to &quot;官网页面资源 404&quot;">​</a></h3><p>确认 Apehub_web 已启用，并检查 <code>/apehub-web</code> 静态挂载是否存在。发布插件包时必须包含 <code>static/docs-portal</code>，但不应包含开发用 <code>node_modules</code>。</p><h2 id="生产检查清单" tabindex="-1">生产检查清单 <a class="header-anchor" href="#生产检查清单" aria-label="Permalink to &quot;生产检查清单&quot;">​</a></h2><ul><li>修改默认管理员密码并限制管理端访问。</li><li>使用环境变量或密钥管理配置数据库、JWT、SMTP、AI 和支付凭据。</li><li>使用迁移脚本而不是依赖自动建表。</li><li>为上传目录配置备份和访问控制。</li><li>验证停用、重新启用、升级和卸载流程，并确认菜单、路由、数据库和文件资源没有残留。</li></ul>',15)])])}const _=a(d,[["render",i]]);export{u as __pageData,_ as default};
